		It.eventMode = Ct.eventMode = "none";
		const _t = tt(It, Ct);
		Ud.attach(Z, It, Ct);
		return Rd.animate(J, (J, tt) => {
			if (It.destroyed || Z._invalid || !Z.d || Z.d.destroyed) return !1;
			Mt(_t, tt);
		}, () => {
			It.destroyed || It.destroy({ children: !0 }), Ct.destroyed || Ct.destroy({ children: !0 });
		}), !0;
